    data_queries = [q for q in ctx.captured_queries if "dataset_statistic" in q["sql"]]
    assert len(data_queries) <= 10, (
        f"Expected ≤10 dataset_statistic queries but got {len(data_queries)}. Pre-refactor baseline was 461."
    )
